class Solution {
public:
    string convertToBase7(int num) {
        if (num == 0) return "0";
        bool neg = num < 0;
        long long n = num;
        if (n < 0) n = -n;
        string s;
        while (n > 0) {
            s += char('0' + (n % 7));
            n /= 7;
        }
        if (neg) s += '-';
        reverse(s.begin(), s.end());
        return s;
    }
};
